#include <WiFi.h>
#include <WebServer.h>

const char* ssid = "ESP32_Void_Compass";
const char* password = "12345678";

WebServer server(80);

int currentStep = 1;
const int maxSteps = 5;

const char htmlPage[] PROGMEM = R"rawliteral(
<!DOCTYPE html>
<html>
<head>
  <meta charset="utf-8">
  <title>Compass to Nothing</title>
  <style>
    body { background: #111; color: #eee; font-family: sans-serif; text-align: center; padding-top: 50px; }
    #counter { font-size: 24px; margin-bottom: 30px; color: #888; }
    #arrow { font-size: 80px; transition: transform 0.2s; display: inline-block; }
    #btn { margin-top: 40px; padding: 15px 30px; font-size: 18px; background: #333; color: #fff; border: 1px solid #555; cursor: pointer; }
  </style>
</head>
<body>
  <div id="counter">Точка <span id="cur">1</span> / 5</div>
  <div id="arrow">&#8593;</div>
  <div><button id="btn" onclick="nextPoint()">Я на месте</button></div>

  <script>
    let angle = Math.random() * 360;
    document.getElementById('arrow').style.transform = `rotate(${angle}deg)`;

    function nextPoint() {
      fetch('/next')
        .then(response => response.json())
        .then(data => {
          document.getElementById('cur').innerText = data.step;
          if(data.step > 5) {
            document.body.innerHTML = "<h1>Пустота достигнута. Больше ничего нет.</h1>";
          } else {
            angle = Math.random() * 360;
            document.getElementById('arrow').style.transform = `rotate(${angle}deg)`;
          }
        });
    }
  </script>
</body>
</html>
)rawliteral";

void handleRoot() {
  server.send_P(200, "text/html", htmlPage);
}

void handleNext() {
  currentStep++;
  if (currentStep > maxSteps) {
    currentStep = maxSteps + 1;
  }
  String json = "{\"step\":" + String(currentStep) + "}";
  server.send(200, "application/json", json);
}

void setup() {
  Serial.begin(115200);
  WiFi.softAP(ssid, password);

  server.on("/", handleRoot);
  server.on("/next", handleNext);
  server.begin();

  Serial.println("Точка доступа создана. Подключись и открой 192.168.4.1");
}

void loop() {
  server.handleClient();
}
